namespace QuantForge.Core;public sealed record AndroidDiagnosticsSummary(int Passed,int Failed,int NotRun,bool RecorderHealthy,string Status);public static class AndroidDiagnosticsSummaryRules{public static AndroidDiagnosticsSummary Create(int passed,int failed,int notRun,bool recorderHealthy){if(passed<0||failed<0||notRun<0)throw new InvalidOperationException("Diagnostic counts cannot be negative.");var status=!recorderHealthy?"Recorder problem":failed>0?"Failures present":notRun>0?"Tests incomplete":"All recorded checks passed";return new(passed,failed,notRun,recorderHealthy,status);}}
